import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1792657777000}`),a={name:`changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to “更新日志”">​</a></h1><p>本页记录曦寒流程设计器各版本的变更，只收使用者能感知的改动。<code>@xihan-flow/core</code>、<code>@xihan-flow/runtime</code>、<code>@xihan-flow/designer</code> 三个包总是同一个版本号一起发布。</p><h2 id="v1-0-0-rc-2-2026-10-22" tabindex="-1">v1.0.0-rc.2（2026-10-22） <a class="header-anchor" href="#v1-0-0-rc-2-2026-10-22" aria-label="Permalink to “v1.0.0-rc.2（2026-10-22）”">​</a></h2><ul><li><strong>新增</strong> 设计器加 <code>closable</code> 属性（同名 attribute）：开着时菜单栏最右端显示一颗关闭钮，按下派发 <code>close</code> 事件，怎么关、要不要先问未保存的修改由宿主决定；缺省不显示。嵌在业务页面里时用它回到列表，见<a href="./guide/host#打开与保存">与宿主集成</a>。</li><li><strong>调整</strong> 设计器的拖动、连线、框选与缩放更流畅：手势进行中只重画画布、覆盖层与状态栏，面板、工具栏、菜单栏与小地图在松手后刷新一次；拖动节点时只给与它相连的连线重新绕线。</li><li><strong>调整</strong> <code>@xihan-ui/*</code> 的 peer 范围提到 <code>^5.1.0</code>：宿主要装 XiHan.UI 5.1.0 及以上，关闭钮与外壳的流畅度改进都在这一版里。</li></ul><h2 id="v1-0-0-rc-1-2026-10-21" tabindex="-1">v1.0.0-rc.1（2026-10-21） <a class="header-anchor" href="#v1-0-0-rc-1-2026-10-21" aria-label="Permalink to “v1.0.0-rc.1（2026-10-21）”">​</a></h2><p>首次发布，以原生 Web Components 交付，不绑定前端框架。</p><ul><li><strong>新增</strong> <code>@xihan-flow/core</code>：流程定义的结构（节点、连线、业务数据与扩展数据）、读入检查、校验与问题码、编辑操作（每一步都能求出逆操作）、连线几何、节点类型登记与扩展合并，纯 TypeScript、不依赖 DOM；<code>@xihan-flow/core/presets/xihan-workflow</code> 是 XiHan 工作流引擎的节点预设，流程定义与引擎定义能互相转换。</li><li><strong>新增</strong> <code>@xihan-flow/runtime</code>：<code>&lt;xh-flow-viewer&gt;</code> 查看器，按节点类型画出流程，标出运行状态与高亮，缩放、平移、定位节点，导出图片；直角连线路由；与 XiHan.UI 内建语言一一对应的界面语言包，查看器与设计器共用。</li><li><strong>新增</strong> <code>@xihan-flow/designer</code>：<code>&lt;xh-flow-designer&gt;</code> 可视化设计器，物料拖放、连线与改连、对齐吸附、自动布局、属性面板、问题列表、流程结构、小地图、撤销重做与历史记录、剪贴板与导出图片；菜单栏、可定制的工具栏与状态栏，设置对话框（主题、语言、布局、工具栏、画布、自动保存本机草稿、开发者模式），新手引导；面板能换栏、收起与浮出。节点类型、属性、规则、命令、面板、物料来源、设置分区、引导步骤与导入导出都能经 <code>extensions</code> 登记。</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};